// PV5: folders, search and filters, moves, folder moves and batches, over the real router, the real index core on
// SQLite and the real policy engine. Fixtures are generated bytes, never real files.

import { createHash, randomBytes } from "node:crypto";
import { DatabaseSync } from "node:sqlite";
import { LibraryIndexCore, ftsQuery, type Sql } from "@media-worker/index-do/core";
import { FakeDigestStream, World, pub, sha256hex, type User } from "./harness.js";
import { jpegWithGps } from "./fixtures.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

const routeKey = (libraryId: string, path: string) => `route:${libraryId}:${createHash("sha256").update(path).digest("hex")}`;
const uuidOf = (p: string) => {
  const h = p.split("_")[1]!;
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
};

describe("library browser: folders, search, moves and batches", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, guest: User;
  let lib: { id: string };
  let libUuid: string;
  let base: string;

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    guest = w.newUser("guest");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Shots" })).json.data.library;
    libUuid = uuidOf(lib.id);
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    await w.call(owner, "POST", `${base}/invitations`, { email: guest.email, role: "uploader" });
    await w.call(guest, "POST", "/v1/media/invitations/accept");
  });

  async function upload(user: User, name: string, folder = "/", extra: Record<string, unknown> = {}, bytes: Uint8Array = randomBytes(64)) {
    const created = await w.call(user, "POST", `${base}/uploads`, { name, folder, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream", ...extra });
    expect(created.status).toBe(201);
    const s = created.json.data.session;
    await w.put(user, `${base}/uploads/${s.id}/parts/1`, bytes);
    const commit = await w.call(user, "POST", `${base}/uploads/${s.id}/commit`);
    expect(commit.status).toBe(200);
    // Public files on a free plan, and images, are served once the pipeline has run (PV4).
    await w.runPipelines();
    return (await w.call(owner, "GET", `${base}/files/${commit.json.data.file.id}`)).json.data.file;
  }

  const list = async (user: User, query: string) => (await w.call(user, "GET", `${base}/files?${query}`)).json.data.files.map((f: { name: string }) => f.name).sort();
  const folders = async () => (await w.call(owner, "GET", `${base}/folders`)).json.data.folders.map((f: { path: string; files: number }) => `${f.path}:${f.files}`);
  const route = (path: string) => JSON.parse(w.kv.get(routeKey(libUuid, path)) ?? "null");

  it("uploads make their folders; the tree lists every folder with its file count; empty folders can be made", async () => {
    await upload(editor, "a.bin", "/photos/2026/may");
    await upload(editor, "b.bin", "/photos/2026/may");
    await upload(editor, "c.bin", "/photos");
    expect((await w.call(editor, "POST", `${base}/folders`, { path: "/drafts" })).status).toBe(201);
    expect(await folders()).toEqual(["/drafts:0", "/photos:1", "/photos/2026:0", "/photos/2026/may:2"]);
    // a viewer sees the tree; a guest uploader too (they can list their own files)
    expect((await w.call(viewer, "GET", `${base}/folders`)).status).toBe(200);
    expect((await w.call(guest, "GET", `${base}/folders`)).status).toBe(200);
    expect((await w.call(viewer, "POST", `${base}/folders`, { path: "/nope" })).status).toBe(404);
    expect((await w.call(editor, "POST", `${base}/folders`, { path: "/_system" })).status).toBe(422);
    expect((await w.call(editor, "POST", `${base}/folders`, { path: "/a/../b" })).status).toBe(422);
  });

  it("search finds files by name words, folder and pipeline tags, as prefixes; filters narrow the list", async () => {
    await upload(editor, "Sunset over Lisbon.bin", "/trips/portugal");
    await upload(editor, "quarterly-report.pdf", "/work", { mime: "application/pdf" });
    await upload(editor, "notes.txt", "/work", { mime: "text/plain", visibility: "public" });
    await upload(guest, "clip.mp4", "/", { mime: "video/mp4" });
    // an image gets tags from the pipeline ("tabby cat", "lynx" from the fake classifier)
    await upload(editor, "kitty.jpg", "/pets", { mime: "image/jpeg" }, jpegWithGps());

    expect(await list(viewer, "q=sun")).toEqual(["Sunset over Lisbon.bin"]);
    expect(await list(viewer, "q=lisb%20sunset")).toEqual(["Sunset over Lisbon.bin"]);
    expect(await list(viewer, "q=portugal")).toEqual(["Sunset over Lisbon.bin"]);
    expect(await list(viewer, "q=tabby")).toEqual(["kitty.jpg"]);
    expect(await list(viewer, "q=report")).toEqual(["quarterly-report.pdf"]);
    expect(await list(viewer, "q=%22%2A%28nothing")).toEqual([]);
    expect(await list(viewer, "type=document")).toEqual(["notes.txt", "quarterly-report.pdf"]);
    expect(await list(viewer, "type=video")).toEqual(["clip.mp4"]);
    expect(await list(viewer, "type=image")).toEqual(["kitty.jpg"]);
    expect(await list(viewer, "type=other")).toEqual(["Sunset over Lisbon.bin"]);
    expect(await list(viewer, "tag=tabby%20cat")).toEqual(["kitty.jpg"]);
    expect(await list(viewer, `uploader=${guest.id}`)).toEqual(["clip.mp4"]);
    expect(await list(viewer, "visibility=public")).toEqual(["notes.txt"]);
    expect(await list(viewer, "status=public")).toEqual(["notes.txt"]);
    expect(await list(viewer, "folder=%2Fwork&q=notes")).toEqual(["notes.txt"]);
    expect(await list(viewer, "from=2026-11-27&to=2026-11-28")).toHaveLength(5);
    expect(await list(viewer, "from=2026-11-28")).toEqual([]);
    expect((await w.call(viewer, "GET", `${base}/tags`)).json.data.tags).toEqual([{ tag: "lynx", files: 1 }, { tag: "tabby cat", files: 1 }]);
    // bad filters are refused, not ignored
    for (const q of ["type=pdf", "status=trashed", "visibility=x", "from=yesterday", "uploader=bob", `q=${"x".repeat(201)}`]) {
      expect([q, (await w.call(viewer, "GET", `${base}/files?${q}`)).status]).toEqual([q, 422]);
    }
    // an uploader who sees only their own files can't widen that with the uploader filter
    expect(await list(guest, `uploader=${editor.id}`)).toEqual(["clip.mp4"]);
    expect(await list(guest, "q=sunset")).toEqual([]);
  });

  it("a file moves and renames; its old path stops serving and the new one serves; conflicts and reserved names are refused", async () => {
    const f = await upload(editor, "logo.bin", "/brand", { visibility: "public" });
    const other = await upload(editor, "taken.bin", "/archive");
    await w.drain();
    expect(route("/brand/logo.bin")).toMatchObject({ f: uuidOf(f.id) });

    const moved = await w.call(editor, "PATCH", `${base}/files/${f.id}`, { folder: "/archive/2026", name: "logo-old.bin" });
    expect(moved.status).toBe(200);
    expect(moved.json.data.file).toMatchObject({ id: f.id, path: "/archive/2026/logo-old.bin", folder: "/archive/2026", name: "logo-old.bin", status: "public" });
    await w.drain();
    expect(route("/brand/logo.bin")).toBeNull();
    expect(route("/archive/2026/logo-old.bin")).toMatchObject({ f: uuidOf(f.id), st: "public" });
    expect(await list(viewer, "q=old")).toEqual(["logo-old.bin"]);
    expect(await folders()).toContain("/archive/2026:1");

    // onto another file's path: 409; reserved; bad names; a viewer can't
    expect((await w.call(editor, "PATCH", `${base}/files/${f.id}`, { folder: "/archive", name: "taken.bin" })).status).toBe(409);
    expect((await w.call(editor, "PATCH", `${base}/files/${f.id}`, { folder: "/", name: "_random" })).status).toBe(422);
    expect((await w.call(editor, "PATCH", `${base}/files/${f.id}`, { name: "a/b" })).status).toBe(422);
    expect((await w.call(editor, "PATCH", `${base}/files/${f.id}`, { colour: "red" })).status).toBe(422);
    expect((await w.call(viewer, "PATCH", `${base}/files/${f.id}`, { name: "x.bin" })).status).toBe(404);
    // a rename and a visibility change together
    const both = await w.call(editor, "PATCH", `${base}/files/${other.id}`, { name: "taken-2.bin", visibility: "public" });
    expect(both.json.data.file).toMatchObject({ name: "taken-2.bin", visibility: "public", status: "processing" }); // free plan: checked first
  });

  it("a taken-down file can't be moved (its 451 stays where it was)", async () => {
    const f = await upload(editor, "bad.bin", "/x", { visibility: "public" });
    const core = [...w.index.cores.values()][0]!;
    core.takedown(uuidOf(f.id), "test", new Date().toISOString());
    const r = await w.call(editor, "PATCH", `${base}/files/${f.id}`, { folder: "/y" });
    expect(r.status).toBe(409);
    expect(r.json.error.details).toMatchObject({ reason: "taken_down" });
    expect((await w.call(editor, "POST", `${base}/folders/move`, { from: "/x", to: "/z" })).status).toBe(409);
  });

  it("a folder moves with its subfolders and files; two concurrent moves of the same folder end in one consistent tree", async () => {
    const ids = [];
    for (const [name, folder] of [["1.bin", "/a"], ["2.bin", "/a/b"], ["3.bin", "/a/b/c"], ["4.bin", "/ab"]] as const) ids.push((await upload(editor, name, folder, { visibility: "public" })).id);
    await w.call(editor, "POST", `${base}/folders`, { path: "/a/empty" });
    const trashed = await upload(editor, "t.bin", "/a");
    await w.call(editor, "DELETE", `${base}/files/${trashed.id}`);
    await w.drain();

    const [x, y] = await Promise.all([
      w.call(editor, "POST", `${base}/folders/move`, { from: "/a", to: "/moved/x" }),
      w.call(editor, "POST", `${base}/folders/move`, { from: "/a", to: "/y" }),
    ]);
    expect([x.status, y.status].sort()).toEqual([200, 404]);
    const winner = x.status === 200 ? "/moved/x" : "/y";
    const loser = winner === "/y" ? "/moved/x" : "/y";
    expect((x.status === 200 ? x : y).json.data).toMatchObject({ moved: 3, folder: { path: winner } });

    const tree = await folders();
    expect(tree.filter((p: string) => p.startsWith("/a:") || p.startsWith("/a/"))).toEqual([]);
    expect(tree.filter((p: string) => p.startsWith(`${loser}:`) || p.startsWith(`${loser}/`))).toEqual([]);
    expect(tree).toEqual(expect.arrayContaining([`${winner}:1`, `${winner}/b:1`, `${winner}/b/c:1`, `${winner}/empty:0`, "/ab:1"]));
    // "/ab" isn't inside "/a"
    const files = (await w.call(viewer, "GET", `${base}/files`)).json.data.files;
    expect(files.map((f: { path: string }) => f.path).sort()).toEqual(["/ab/4.bin", `${winner}/1.bin`, `${winner}/b/2.bin`, `${winner}/b/c/3.bin`].sort());
    await w.drain();
    expect(route("/a/1.bin")).toBeNull();
    expect(route("/a/b/c/3.bin")).toBeNull();
    expect(route(`${winner}/b/c/3.bin`)).toMatchObject({ f: uuidOf(ids[2]) });
    expect(route("/ab/4.bin")).toMatchObject({ f: uuidOf(ids[3]) });
    // the trashed file moved too, so a restore lands it in the moved folder
    const restored = await w.call(editor, "POST", `${base}/files/${trashed.id}/restore`);
    expect(restored.json.data.file.path).toBe(`${winner}/t.bin`);

    // onto an existing folder, into itself, the root: refused
    expect((await w.call(editor, "POST", `${base}/folders/move`, { from: winner, to: "/ab" })).status).toBe(409);
    expect((await w.call(editor, "POST", `${base}/folders/move`, { from: winner, to: `${winner}/b/inner` })).status).toBe(422);
    expect((await w.call(editor, "POST", `${base}/folders/move`, { from: "/", to: "/z" })).status).toBe(422);
    expect((await w.call(viewer, "POST", `${base}/folders/move`, { from: winner, to: "/z" })).status).toBe(404);
  });

  it("a bulk move of 1,000 files completes in one transaction and the index and routes stay consistent", async () => {
    const first = await upload(editor, "seed.bin", "/inbox", { visibility: "public" });
    const core = [...w.index.cores.values()][0]!;
    const ids = [first.id];
    const now = new Date().toISOString();
    for (let i = 1; i < 1000; i++) {
      const id = crypto.randomUUID();
      core.commit({ fileId: id, path: `/inbox/f${i}.bin`, name: `f${i}.bin`, folder: "/inbox", size: 64, sha256: first.sha256, mime: "application/octet-stream", visibility: "public", replace: false, objectKey: null, actor: editor.id, nowIso: now });
      ids.push(pub("fil", id));
    }
    // one of them already exists at the destination: it fails alone, the rest move
    await upload(editor, "f7.bin", "/sorted");
    await w.drain();

    const t0 = Date.now();
    const r = await w.call(editor, "POST", `${base}/files:batch`, { action: "move", ids, folder: "/sorted" });
    const ms = Date.now() - t0;
    expect(r.status).toBe(200);
    expect(r.json.data.done).toBe(999);
    expect(r.json.data.failed).toEqual([{ id: ids[7], code: "conflict" }]);
    expect(r.json.data.files).toBeUndefined(); // large batches return counts only
    expect(ms).toBeLessThan(5000);

    expect(await folders()).toEqual(["/inbox:1", "/sorted:1000"]);
    const all: string[] = [];
    let cursor: string | null = null;
    do {
      const page: { json: { data: { files: { path: string }[]; nextCursor: string | null } } } = await w.call(viewer, "GET", `${base}/files?limit=200${cursor ? `&cursor=${encodeURIComponent(cursor)}` : ""}`);
      all.push(...page.json.data.files.map((f) => f.path));
      cursor = page.json.data.nextCursor;
    } while (cursor);
    expect(all).toHaveLength(1001);
    expect(new Set(all).size).toBe(1001);
    expect(all.filter((p) => p.startsWith("/inbox/"))).toEqual(["/inbox/f7.bin"]);
    expect(await list(viewer, "folder=%2Fsorted&q=f999")).toEqual(["f999.bin"]);

    // serving: every moved file answers at its new path, none at the old one
    await w.drain();
    expect(route("/inbox/f500.bin")).toBeNull();
    expect(route("/sorted/f500.bin")).toMatchObject({ st: "public" });
    expect(route("/inbox/f7.bin")).toMatchObject({ st: "public" });
    expect([...w.kv.keys()].filter((k) => k.startsWith(`route:${libUuid}:`))).toHaveLength(1001);

    // too many, or nothing: refused
    expect((await w.call(editor, "POST", `${base}/files:batch`, { action: "move", ids: [...ids, ids[0]].concat(ids.slice(0, 1)), folder: "/x" })).status).toBe(422);
    expect((await w.call(editor, "POST", `${base}/files:batch`, { action: "move", ids: [], folder: "/x" })).status).toBe(422);
  });

  it("batches trash, restore and change visibility; each needs its own permission; unknown ids fail alone", async () => {
    const a = await upload(editor, "a.bin", "/b", { visibility: "private" });
    const b = await upload(editor, "b.bin", "/b", { visibility: "private" });
    const vis = await w.call(editor, "POST", `${base}/files:batch`, { action: "visibility", ids: [a.id, b.id, "fil_nope"], visibility: "public" });
    expect(vis.status).toBe(200);
    expect(vis.json.data.done).toBe(2);
    expect(vis.json.data.failed).toEqual([{ id: "fil_nope", code: "not_found" }]);
    // a public file on a free plan goes through the safety check first
    expect(vis.json.data.files.map((f: { status: string }) => f.status)).toEqual(["processing", "processing"]);
    expect(w.workflows).toHaveLength(2);

    expect((await w.call(guest, "POST", `${base}/files:batch`, { action: "trash", ids: [a.id] })).status).toBe(404);
    expect((await w.call(viewer, "POST", `${base}/files:batch`, { action: "trash", ids: [a.id] })).status).toBe(404);
    const tr = await w.call(editor, "POST", `${base}/files:batch`, { action: "trash", ids: [a.id, b.id] });
    expect(tr.json.data.done).toBe(2);
    expect(await list(viewer, "")).toEqual([]);
    const re = await w.call(editor, "POST", `${base}/files:batch`, { action: "restore", ids: [a.id, b.id] });
    expect(re.json.data.done).toBe(2);
    expect((await w.call(editor, "POST", `${base}/files:batch`, { action: "zip", ids: [a.id] })).status).toBe(422);
  });

  it("trashing a folder trashes every file under it and removes the folder", async () => {
    await upload(editor, "1.bin", "/old");
    await upload(editor, "2.bin", "/old/deeper");
    await upload(editor, "3.bin", "/keep");
    const r = await w.call(editor, "POST", `${base}/folders/trash`, { path: "/old" });
    expect(r.json.data).toEqual({ trashed: 2 });
    expect(await folders()).toEqual(["/keep:1"]);
    expect(await list(editor, "trash=1")).toEqual(["1.bin", "2.bin"]);
    expect((await w.call(viewer, "POST", `${base}/folders/trash`, { path: "/keep" })).status).toBe(404);
    expect((await w.call(editor, "POST", `${base}/folders/trash`, { path: "/missing" })).status).toBe(404);
  });
});

describe("the search index", () => {
  function core(db: DatabaseSync): LibraryIndexCore {
    const sql: Sql = {
      exec: (q, ...p) => {
        const rows = db.prepare(q).all(...(p as never[])) as never[];
        return { toArray: () => rows };
      },
      transaction: (fn) => {
        db.exec("BEGIN");
        try {
          const r = fn();
          db.exec("COMMIT");
          return r;
        } catch (e) {
          db.exec("ROLLBACK");
          throw e;
        }
      },
    };
    return new LibraryIndexCore(sql);
  }

  it("an index made before PV5 fills its search index and folders when it starts", () => {
    const db = new DatabaseSync(":memory:");
    const c = core(db);
    c.assertScope({ orgId: "o", libraryId: "l" });
    const now = new Date().toISOString();
    c.commit({ fileId: "f1", path: "/x/y/harbour.bin", name: "harbour.bin", folder: "/x/y", size: 1, sha256: "a".repeat(64), mime: "application/octet-stream", visibility: "private", replace: false, objectKey: "k", actor: "u", nowIso: now });
    // forget what PV5 added, as an older index would lack it
    db.exec(`DELETE FROM files_fts; DELETE FROM fts_map; DELETE FROM folders; DELETE FROM meta WHERE key = 'browse_v'`);
    expect(c.listFiles({ q: "harb", limit: 10 }).files).toHaveLength(0);
    const again = core(db);
    expect(again.listFiles({ q: "harb", limit: 10 }).files.map((f) => f.id)).toEqual(["f1"]);
    expect(again.listFolders().map((f) => f.path)).toEqual(["/x", "/x/y"]);
    // a purge removes it from the index too
    again.trash("f1", now);
    again.purge("f1");
    expect(db.prepare(`SELECT COUNT(*) AS n FROM files_fts`).get()).toEqual({ n: 0 });
  });

  it("free text becomes a safe FTS query", () => {
    expect(ftsQuery("Sunset  over")).toBe('"Sunset"* "over"*');
    expect(ftsQuery('a"b OR c*')).toBe('"a"* "b"* "OR"* "c"*');
    expect(ftsQuery("  ** () ")).toBeNull();
  });
});
